import csv, json, collections

# Load names from the offboarding list (read-only)
names = collections.OrderedDict()
with open('/testbed/data/offboarding_list.csv') as f:
    for row in csv.DictReader(f):
        names[row['employee_id'].strip()] = row['full_name'].strip()

# Load checker output
data = json.load(open('/tmp/check_output.json'))

PRIV_NAME = {'vpn': 'VPN Access', 'gitlab': 'GitLab Access', 'wiki': 'Internal Wiki Access'}

# Task judgment rule: status != 'active'  ->  privilege_revoked = true
def revoked_flag(status):
    if status == 'active':
        return False
    if status in ('revoked', 'scheduled'):
        return True
    return None  # unknown status -> cannot determine

by_emp = collections.OrderedDict()
for p in data['privileges']:
    by_emp.setdefault(p['employee_id'], []).append(p)

employee_details = []
total_priv = 0
revoked_true = 0
not_fully = []
unknown = []

for emp_id, privs in by_emp.items():
    entries = []
    flags = []
    for p in privs:
        flag = revoked_flag(p['status'])
        flags.append(flag)
        total_priv += 1
        if flag is True:
            revoked_true += 1
        if flag is None:
            unknown.append((emp_id, p['system'], p['status']))
        entries.append({
            'privilege_name': PRIV_NAME.get(p['system'], p['system']),
            'system': p['system'],
            'privilege_revoked': flag,
        })
    if all(x is True for x in flags):
        emp_all = True
    elif any(x is False for x in flags):
        emp_all = False
        not_fully.append(emp_id)
    else:
        emp_all = None
        not_fully.append(emp_id)
    employee_details.append({
        'employee_id': emp_id,
        'employee_name': names.get(emp_id, ''),
        'privileges': entries,
        'all_privileges_revoked': emp_all,
    })

if total_priv == revoked_true and total_priv > 0 and not unknown:
    summary_all = True
elif not_fully:
    summary_all = False
else:
    summary_all = None

report = {
    'report_metadata': {
        'audit_timestamp': data['timestamp'],
        'auditor': 'Codex CLI agent (automated offboarding access revocation audit)',
        'report_version': '1.0',
    },
    'summary': {
        'total_employees_checked': len(employee_details),
        'total_privileges_checked': total_priv,
        'successfully_revoked_count': revoked_true,
        'all_privileges_revoked': summary_all,
    },
    'employee_details': employee_details,
    'findings': {
        'employees_notfully_revoked': sorted(set(not_fully)),
    },
    'conclusion': '',
}

# conclusion text
lines = []
lines.append('Audit result: PRIVILEGES STILL NOT REVOKED.')
lines.append(
    'Checked %d offboarded employees and %d system privileges (VPN, GitLab, Internal Wiki) '
    'using check_revocation.py output taken at %s.' % (len(employee_details), total_priv, data['timestamp'])
)
lines.append(
    'Judgment rule applied: privilege_revoked = true when the reported status is not "active" '
    '(i.e., "revoked" and "scheduled" both count as revoked).'
)
lines.append(
    'Under this rule %d of %d privileges are confirmed revoked (%s) and %d is not revoked.'
    % (revoked_true, total_priv,
       ', '.join('%d revoked + %d scheduled' % (data['status_counts']['revoked'], data['status_counts']['scheduled'])),
       data['status_counts']['active'])
)
lines.append(
    'Outstanding item: emp_008 (Henry Yang) VPN access is still "active" (last access 2026-09-07), '
    'so it is NOT revoked and requires immediate remediation.'
)
lines.append(
    'Note: emp_009 (Iris Huang) GitLab access is "scheduled" rather than fully "revoked"; it is counted as '
    'revoked per the stated rule, but the scheduled revocation should be verified as executed.'
)
lines.append(
    'All other 8 employees (emp_001-emp_007, emp_010) have all three privileges revoked.'
)
report['conclusion'] = ' '.join(lines)

with open('/testbed/revocation_report.json', 'w') as f:
    json.dump(report, f, indent=2, ensure_ascii=False)
    f.write('\n')

print('unknown statuses:', unknown)
print('not fully revoked:', report['findings']['employees_notfully_revoked'])
print('summary:', report['summary'])
